    "subtopic": "Overview",
    "content_html": "<div class=\"text-center\">\r\n<button type=\"button\" class=\"btn btn-light shadow-lg\">$\\Sigma F = ma_c$ <span class=\"text-muted\">&emsp; &emsp; &emsp; Page 109</span></button>\r\n</div><br/>\r\n\r\n\r\n<div class=\"text-center\">\r\n<button type=\"button\" class=\"btn btn-light shadow-lg\">$\\Sigma M_c = I_c \\alpha$ <span class=\"text-muted\">&emsp; &emsp; &emsp; Page 109</span></button>\r\n</div><br/>\r\n\r\n<div class=\"text-center\">\r\n<button type=\"button\" class=\"btn btn-light shadow-lg\">$\\Sigma M_p = I_c \\alpha + \\rho_{pc} \\times ma_c$ <span class=\"text-muted\">&emsp; &emsp; &emsp; Page 109</span></button>\r\n</div><br/>",
    "important": "\\[\\Sigma F = ma_c\\]\r\n\\[\\Sigma M_c = I_c \\alpha\\]\r\n\\[\\Sigma M_p = I_c \\alpha + \\rho_{pc} \\times ma_c\\]",
