    "content_html": "<div class= \"container-fluid\">\r\n  <div class= \"row align-items-start\">\r\n   <div class=\"col col-lg-8\">\r\n   <div class=\"text-center\">\r\n<button type=\"button\" class=\"btn btn-light shadow-lg\">$I_{new} = I_c + md^2$ <span class=\"text-muted\">&emsp; &emsp; &emsp; Page 111</span></button>\r\n</div><br/>\r\n<span class=\"math inline\">\\(I_{new}\\)</span> = the mass moment of inertia about any specified axis<br />\r\n<span class=\"math inline\">\\(I_c\\)</span> = the mass moment of inertia about an axis parallel to the above specified axis but passes through the body’s mass center.<br />\r\nm = mass of the body<br />\r\nd = normal distance from the body’s mass center to the above specified axis.</p>\r\n    </div>\r\n    <div class=\"col\">\r\n<center><img src=\"https://onedrive.live.com/embed?resid=9C913AE725AFDEB1%21573&authkey=%21ABHeZtxwKU32WPA&width=288&height=200\" width=\"288\" height=\"200\" /></center>\r\n    </div>\r\n  </div>\r\n</div>",
