    "discipline": "Civil",
    "subject": "Fluid Mechanics",
    "chapter": "Scaling Laws for Fans, Pumps and Compressors",
    "topic": "NPSH and Cavitation",
    "subtopic": "Scaling Laws",
    "content_html": "<div class=\"text-center\">\r\n<button type=\"button\" class=\"btn btn-light shadow-lg\">$\\left(\\dfrac{Q}{ND^3}\\right)_2 = \\left(\\dfrac{Q}{ND^3}\\right)_1$ <span class=\"text-muted\">&emsp; &emsp; &emsp; Page 195</span></button>\r\n</div><br/>\r\n\r\n<div class=\"text-center\">\r\n<button type=\"button\" class=\"btn btn-light shadow-lg\">$\\left(\\dfrac{\\dot{m}}{\\rho ND^3}\\right)_2 = \\left(\\dfrac{\\dot{m}}{\\rho ND^3}\\right)_1$ <span class=\"text-muted\">&emsp; &emsp; &emsp; Page 195</span></button>\r\n</div><br/>\r\n\r\n<div class=\"text-center\">\r\n<button type=\"button\" class=\"btn btn-light shadow-lg\">$\\left(\\dfrac{H}{N^2D^2}\\right)_2 = \\left(\\dfrac{H}{N^2D^2}\\right)_1$ <span class=\"text-muted\">&emsp; &emsp; &emsp; Page 195</span></button>\r\n</div><br/>\r\n\r\n<div class=\"text-center\">\r\n<button type=\"button\" class=\"btn btn-light shadow-lg\">$\\left(\\dfrac{P}{\\rho N^2D^2}\\right)_2 = \\left(\\dfrac{P}{\\rho N^2D^2}\\right)_1$ <span class=\"text-muted\">&emsp; &emsp; &emsp; Page 195</span></button>\r\n</div><br/>\r\n\r\n<div class=\"text-center\">\r\n<button type=\"button\" class=\"btn btn-light shadow-lg\">$\\left(\\dfrac{\\dot{W}}{\\rho N^3D^5}\\right)_2 = \\left(\\dfrac{\\dot{W}}{\\rho N^3D^5}\\right)_1$ <span class=\"text-muted\">&emsp; &emsp; &emsp; Page 195</span></button>\r\n</div><br/>",
